WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, attr_value), base AS (SELECT *, CONCAT_WS(',', host, attr_key) AS host_attr_key_key FROM flattened WHERE attr_key IS NOT NULL AND status_code <> 312), flagged AS (SELECT *, CASE WHEN log_ts - LAG(log_ts) OVER (PARTITION BY service ORDER BY log_ts, id, attr_key) > INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY service ORDER BY log_ts, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged), enriched AS (SELECT id, service, host, log_ts, latency_ms, status_code, attr_key, attr_value, host_attr_key_key, session_start_flag, FIRST_VALUE(attr_key) IGNORE NULLS OVER (PARTITION BY attr_key ORDER BY session_no, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_attr_key, NTILE(3) OVER (PARTITION BY host ORDER BY session_no DESC, id, attr_key) AS session_no_bucket FROM sessionized), latest AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY host ORDER BY session_no_bucket DESC NULLS FIRST, id, attr_key) = 1) SELECT id, status_code, attr_key, attr_value, host_attr_key_key, session_start_flag, first_known_attr_key, CASE WHEN attr_key RLIKE '^(region|version)$' THEN 'PRIORITY' WHEN attr_key RLIKE '^(trace)$' THEN 'CORE' ELSE 'GROUP_A' END AS attr_key_zone FROM latest;
